// Regenerates public/sitemap.xml and public/robots.txt from siteConfig.siteUrl and the shared
// public route list (PCD families/tools, Applications and News hidden). Run: bun scripts/sitemap.ts
import { writeFileSync } from 'node:fs';
import { siteConfig } from '../src/lib/siteConfig';
import { publicRoutes } from '../src/lib/publicRoutes';

const url = (path: string) => `${siteConfig.siteUrl}${path === '/' ? '/' : path}`;

writeFileSync(new URL('../public/sitemap.xml', import.meta.url), `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by scripts/sitemap.ts from src/lib/publicRoutes.ts. Each URL is a real path served as
     pre-rendered HTML (scripts/prerender.ts). lastmod is omitted because authoritative page-specific
     content dates are unavailable. -->
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${publicRoutes().map(p => `  <url><loc>${url(p)}</loc></url>`).join('\n')}
</urlset>
`);

writeFileSync(new URL('../public/robots.txt', import.meta.url), `# Public business website: allow search engines to crawl.
# Generated by scripts/sitemap.ts.
User-agent: *
Allow: /

Sitemap: ${siteConfig.siteUrl}/sitemap.xml
`);
